let data;
try {
    const lines = msg.payload.trim().split('\n');
    const lastLine = lines[lines.length - 1];
    data = JSON.parse(lastLine);
} catch (e) {
    msg.statusText = '⚠️ Parse-Fehler: ' + msg.payload;
    flow.set('letzterFehler', msg.payload);
    return [null, null, msg, null];
}

if (!data.ok) {
    msg.statusText = '⚠️ Fehler: ' + (data.error || 'unbekannt') + (data.detail ? ' (' + data.detail + ')' : '');
    flow.set('letzterFehler', data.error || 'unbekannt');
    return [null, null, msg, null];
}

const gasMsg = {
    payload: data.gas_percent,
    topic: 'rotarex/gasflasche/prozent'
};

// Der Batteriestand des Senders ist optional. Fehlt er, wird bewusst nichts
// veroeffentlicht: Ein retained MQTT-Wert null bliebe stehen und saehe aus
// wie eine leere Batterie.
const batterieDa = typeof data.battery_percent === 'number';
const battMsg = batterieDa
    ? { ...msg, payload: data.battery_percent, topic: 'rotarex/gasflasche/batterie' }
    : null;

const hinweise = [];
if (!batterieDa) {
    hinweise.push('Sender-Batterie: keine Angabe' + (data.battery_error ? ' (' + data.battery_error + ')' : ''));
}
if (data.history_error) {
    hinweise.push('⚠️ History: ' + data.history_error);
}

msg.statusText = '⛽ Gasflasche: ' + data.gas_percent + '% (roh: ' + data.gas_raw + ')'
    + (batterieDa ? ' | Sender-Batterie: ' + data.battery_percent + '%' : '')
    + (hinweise.length ? ' | ' + hinweise.join(' | ') : '');

flow.set('letzterGasstand', data.gas_percent);
flow.set('letzteMessung', new Date().toISOString());
flow.set('letzterFehler', data.history_error || null);

// FLASCHENGROESSE - Stelle 2 von 2.
// Die andere ist das Feld Capacity im Knoten "LPG" (tank_capacity).
// Beide muessen denselben Wert haben, sonst rechnet die VRM-Konsole
// mit der einen und das GX-Touch-Display mit der anderen Zahl.
//   5 kg  = 0.0105     11 kg = 0.021     14 kg = 0.0275
//
// Warum nicht alles hier: Der victron-virtual-Knoten legt /Capacity und
// /FluidType beim Start aus seiner eigenen Konfiguration an und ignoriert
// beide Pfade im Payload. Nachgemessen am 12.09.2026 - ein von Hand auf
// 0.025 gesetztes /Capacity stand auch nach einem erfolgreichen Abruf
// unveraendert da. Aus dem Payload uebernimmt der Knoten nur /Level,
// /Remaining und /Status.
const KAPAZITAET_M3 = 0.021;

// /Remaining muss mit. Die VRM-Konsole rechnet den Literwert selbst aus
// Capacity x Level, das GX-Touch-Display zeigt dagegen den letzten je
// empfangenen /Remaining-Wert. Fehlt er, steht dort eine eingefrorene
// falsche Literangabe (beobachtet: 8 von 21 L bei 99 Prozent), waehrend
// VRM daneben korrekt rechnet. Auf mm3 gerundet, damit keine
// Fliesskomma-Reste auf den D-Bus gehen.
const restM3 = Math.round(data.gas_percent / 100 * KAPAZITAET_M3 * 1e9) / 1e9;

const tankMsg = {
    payload: {
        '/Level': data.gas_percent,
        '/Remaining': restM3,
        '/Status': 0
    }
};

return [gasMsg, battMsg, msg, tankMsg];
